"""P30 + P31 harness: P13's method at survey scale; xl ingest 1 measured under /usr/bin/time -l (P30).

Usage: python p31_harness.py RUN_ROOT REPO_ROOT > receipt.json
Synthetic data only. RUN_ROOT must not exist; the caller harvests and deletes it.
"""
from __future__ import annotations
import hashlib, json, re, shutil, subprocess, sys, time
from pathlib import Path
from typing import Any

RUN_ROOT = Path(sys.argv[1]).resolve()
REPO = Path(sys.argv[2]).resolve()
SDIP = str(REPO / ".venv" / "bin" / "sdip")
sys.path.insert(0, str(REPO))
PAUSE_S = 1.5
WANT = {"large_ibm32": "2b8b7aa0851771ae8d2981ed173de63f7dd94f0b50124d3a7bf2881b9cd3eb2e",
        "xl_ibm32": "7ac9dfb25d4b1f44976931df37568e86e3f950d8687d791c3c3c369a89a30817"}
CASES = [("xl_ibm32", 3), ("large_ibm32", 5), ("large_float32", 5)]

def sha(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for b in iter(lambda: f.read(1 << 24), b""): h.update(b)
    return h.hexdigest()

def make(case: str, path: Path) -> None:
    from tests.fixtures.generators.poststack3d import make_poststack3d
    if case == "xl_ibm32":
        with path.open("wb") as f:
            for k in range(6):
                piece = make_poststack3d(RUN_ROOT / f"piece{k}.sgy", n_inline=300, n_crossline=630,
                                         n_samples=1000, inline_start=100 + 300 * k).path
                with piece.open("rb") as p:
                    head = p.read(3600)
                    if k == 0: f.write(head)
                    shutil.copyfileobj(p, f, 1 << 24)
                piece.unlink()
    else:
        fmt = "float32" if case.endswith("float32") else "ibm32"
        make_poststack3d(path, n_inline=600, n_crossline=630, n_samples=1000, sample_format=fmt)

def flatten(value: Any, prefix: str = "") -> dict[str, Any]:
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        for k, v in value.items(): out.update(flatten(v, f"{prefix}/{k}"))
        return out
    if isinstance(value, str) and value.startswith("{"):
        try:
            return flatten(json.loads(value), prefix)  # statsV1 is a JSON string; flatten it too
        except ValueError:
            pass
    return {prefix: json.dumps(value, sort_keys=True)}

def survey(store: Path) -> tuple[dict[str, str], dict[str, dict[str, Any]]]:
    chunks, metadata = {}, {}
    for path in sorted(store.rglob("*")):
        if not path.is_file(): continue
        rel = path.relative_to(store).as_posix()
        if path.name == "zarr.json": metadata[rel] = flatten(json.loads(path.read_bytes()))
        else: chunks[rel] = sha(path)
    return chunks, metadata

def main() -> None:
    RUN_ROOT.mkdir(parents=True, exist_ok=False)
    commit = subprocess.run(["git", "-C", str(REPO), "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    dirty = subprocess.run(["git", "-C", str(REPO), "status", "--porcelain"], capture_output=True, text=True).stdout
    report: dict[str, Any] = {"probe": "P31", "commit": commit, "tree_clean": not dirty, "cases": {}, "p30": None}
    for case, n in CASES:
        source = RUN_ROOT / f"{case}.sgy"
        make(case, source)
        digest = sha(source)
        if case in WANT and digest != WANT[case]:
            report["cases"][case] = {"error": f"fixture sha256 {digest} != registered"}; break
        runs, seconds = [], []
        for i in range(n):
            store = RUN_ROOT / f"{case}-{i}.mdio"
            argv = [SDIP, "ingest", str(source), str(store)]
            if case == "xl_ibm32" and i == 0: argv = ["/usr/bin/time", "-l", *argv]
            t = time.monotonic()
            proc = subprocess.run(argv, capture_output=True, text=True, check=False, cwd=REPO)
            seconds.append(round(time.monotonic() - t, 1))
            if case == "xl_ibm32" and i == 0:
                m = re.search(r"(\d+)\s+maximum resident set size", proc.stderr)
                report["p30"] = {"exit": proc.returncode, "source_bytes": source.stat().st_size,
                                 "peak_rss_bytes": int(m.group(1)) if m else None, "real_s": seconds[-1]}
            if proc.returncode != 0:
                runs.append({"error": proc.stderr[-600:]}); continue
            runs.append(survey(store)); shutil.rmtree(store); time.sleep(PAUSE_S)
        good = [r for r in runs if isinstance(r, tuple)]
        entry: dict[str, Any] = {"N": n, "source_bytes": source.stat().st_size, "source_sha256": digest, "ingest_s": seconds}
        if len(good) != n:
            entry["error"] = [r for r in runs if isinstance(r, dict)]
        else:
            chunk_diff = sorted(rel for rel in set().union(*(set(c) for c, _ in good)) if len({c.get(rel) for c, _ in good}) > 1)
            varying: dict[str, list[str]] = {}
            for rel in set().union(*(set(m) for _, m in good)):
                for key in set().union(*(set(m.get(rel, {})) for _, m in good)):
                    vals = [m.get(rel, {}).get(key) for _, m in good]
                    if len(set(vals)) > 1: varying[f"{rel}#{key}"] = vals
            entry.update({"chunk_files": len(good[0][0]), "chunk_files_differing": chunk_diff,
                          "metadata_keys_differing": dict(sorted(varying.items()))})
        report["cases"][case] = entry
        source.unlink()
        if entry.get("chunk_files_differing"): break  # the falsifier: stop
    print(json.dumps(report, indent=1))

if __name__ == "__main__":
    main()
